update public.iwb_content set available=false where kind='coding' and problem_id='0011-conveyor-permit-route' and revision<>'016351dcefbb86749420235d13fbe19034043dff874eff450de76e7388ec8bee';
insert into public.iwb_content(kind, problem_id, revision, payload, scaffold) values ('coding', '0011-conveyor-permit-route', '016351dcefbb86749420235d13fbe19034043dff874eff450de76e7388ec8bee', '{"id":"0011-conveyor-permit-route","title":"Conveyor Permit Route","difficulty":"medium","tags":["graph","breadth-first-search"],"pattern_tags":["bfs","expanded-state","resource-state"],"description_md":"A warehouse has numbered stations connected by one-way conveyor links. Each link is represented as [from, to, permit_delta]. Moving across a link always takes one step. A negative permit_delta consumes permits, while a positive permit_delta restores permits up to a fixed cap. Return the fewest steps from start to target without ever dropping below zero permits, or -1 if the target cannot be reached.","examples":[{"input":"station_count=4, links=[[0,1,-1],[0,2,0],[2,1,1],[1,3,-1]], start=0, target=3, permits=1, permit_cap=2","output":"3","explanation":"The route through station 2 reaches station 1 with more permits available, allowing the final restricted conveyor."}],"constraints":["1 <= station_count <= 100000","0 <= len(links) <= 200000","0 <= start, target < station_count","0 <= permits <= permit_cap <= 20","Each link is [from, to, permit_delta] with valid station indices.","-permit_cap <= permit_delta <= permit_cap for every link."],"starter_code":{"python":"def fewest_conveyor_steps(station_count: int, links: list[list[int]], start: int, target: int, permits: int, permit_cap: int) -> int:\n    \"\"\"Example call and expected return.\n\n    >>> fewest_conveyor_steps(\n    ...     4, [[0, 1, -1], [0, 2, 0], [2, 1, 1], [1, 3, -1]], 0, 3, 1, 2\n    ... )\n    3\n    \"\"\"\n    pass\n"},"test_cases":{"python":[{"input":[4,[[0,1,-1],[0,2,0],[2,1,1],[1,3,-1]],0,3,1,2],"expected":3},{"input":[3,[[0,1,-1],[1,2,-1]],0,2,1,1],"expected":-1},{"input":[1,[],0,0,0,0],"expected":0},{"input":[5,[[0,1,0],[1,4,-1],[0,2,0],[2,3,0],[3,4,0]],0,4,0,1],"expected":3},{"input":[4,[[0,1,-1],[0,2,0],[2,1,1],[1,3,-2]],0,3,1,2],"expected":3},{"input":[4,[[0,1,2],[1,2,2],[2,3,-3]],0,3,0,2],"expected":-1},{"input":[6,[[0,1,0],[1,5,-1],[0,2,0],[2,3,1],[3,1,0],[1,4,-2],[4,5,0]],0,5,1,2],"expected":2},{"input":[3,[[1,0,0],[1,2,0]],0,2,0,0],"expected":-1}]},"canonical_solution_md":"Use breadth-first search because every conveyor traversal has the same step cost. The state must include both the current station and current permit count. For each outgoing link, compute the next permit count after applying the link delta, discard moves that would go below zero, and cap restored permits at the maximum. A station reached with more permits can enable different future moves, so visited tracking must include the permit count. The first time the target state is reached gives the fewest steps.","fallback_hints":["Think about whether being at a station is enough information to know what moves are still possible.","The same station can be more useful when reached with more permits available.","Use a shortest-path search over station and permit count together, and ignore transitions that would make permits negative."],"common_mistakes":["Marking only stations as visited and throwing away a later state with more permits.","Letting restored permits exceed the permit cap.","Using depth-first search and assuming the first route found is shortest.","Treating one-way conveyor links as bidirectional."],"follow_up_questions":["How would the approach change if conveyors had different traversal times?","How would you reconstruct the actual route instead of only the step count?","What changes if permit restoration only happens once per station?"],"suboptimal_solutions":[{"name":"DFS over all routes","complexity":"Exponential","description":"Explores many repeated states and does not naturally guarantee the fewest steps."},{"name":"BFS with station-only visited","complexity":"Incorrect","description":"Can discard a later visit to the same station that has more permits and is necessary for a valid route."}],"created_at":"2026-01-01T00:00:00Z","updated_at":"2026-01-01T00:00:00Z"}'::jsonb, '{"relative_path":"0011-conveyor-permit-route/solution.py","language":"python","contents":"# ------------------------------------------------------------\n# [0011-conveyor-permit-route] Conveyor Permit Route  |  medium  |  bfs\n# ------------------------------------------------------------\n# A warehouse has numbered stations connected by one-way conveyor links. Each link is represented as [from, to, permit_delta]. Moving across a link always takes one step. A negative permit_delta consumes permits, while a positive permit_delta restores permits up to a fixed cap. Return the fewest steps from start to target without ever dropping below zero permits, or -1 if the target cannot be reached.\n#\n# Example: station_count=4, links=[[0,1,-1],[0,2,0],[2,1,1],[1,3,-1]], start=0, target=3, permits=1, permit_cap=2 -> 3\n#\n# Full description: call get_problem_description(attempt_id)\n# ------------------------------------------------------------\n\ndef fewest_conveyor_steps(station_count: int, links: list[list[int]], start: int, target: int, permits: int, permit_cap: int) -> int:\n    \"\"\"Example call and expected return.\n\n    >>> fewest_conveyor_steps(\n    ...     4, [[0, 1, -1], [0, 2, 0], [2, 1, 1], [1, 3, -1]], 0, 3, 1, 2\n    ... )\n    3\n    \"\"\"\n    pass\n","sha256":"c86143806efc9522c844e279b2fe78630ebae133d5b942a3577079569254c10e"}'::jsonb) on conflict (kind, problem_id, revision) do update set available=true;
update public.iwb_content set available=false where kind='coding' and problem_id='0012-training-mix-segment' and revision<>'a019609591fe26c81cd4788d8c1bd5b4193eeba39e493b22c3736ade54464c4e';
insert into public.iwb_content(kind, problem_id, revision, payload, scaffold) values ('coding', '0012-training-mix-segment', 'a019609591fe26c81cd4788d8c1bd5b4193eeba39e493b22c3736ade54464c4e', '{"id":"0012-training-mix-segment","title":"Training Mix Segment","difficulty":"medium","tags":["array","hash-map","sliding-window"],"pattern_tags":["sliding-window","frequency-map"],"description_md":"A training platform records lesson categories in the order a learner completes them. A segment is balanced if no category appears more than max_per_category times inside that contiguous segment. Return the length of the longest balanced segment.","examples":[{"input":"lessons=[\"sql\", \"api\", \"sql\", \"sql\", \"testing\"], max_per_category=2","output":"4","explanation":"The segment [\"api\", \"sql\", \"sql\", \"testing\"] is balanced and has length 4."}],"constraints":["0 <= len(lessons) <= 100000","1 <= max_per_category <= 100000","Each lesson category is a non-empty string."],"starter_code":{"python":"def longest_balanced_training_segment(lessons: list[str], max_per_category: int) -> int:\n    \"\"\"Example call and expected return.\n\n    >>> longest_balanced_training_segment([\"sql\", \"api\", \"sql\", \"sql\", \"testing\"], 2)\n    4\n    \"\"\"\n    pass\n"},"test_cases":{"python":[{"input":[["sql","api","sql","sql","testing"],2],"expected":4},{"input":[[],2],"expected":0},{"input":[["a","b","c"],1],"expected":3},{"input":[["a","a","a"],1],"expected":1},{"input":[["a","b","a","c","a","d"],2],"expected":5},{"input":[["x","x","y","x","y","y"],2],"expected":5},{"input":[["a","b","b","a","b","c","b"],2],"expected":5}]},"canonical_solution_md":"Move a right boundary across the lesson list while keeping counts for the active segment. If adding a lesson makes its category exceed the allowed count, move the left boundary forward and decrement counts until the active segment is balanced again. After each repair, measure the current segment length. Each boundary moves forward at most once, so the scan is linear.","fallback_hints":["Think about a current contiguous segment that can grow and then be repaired.","A count table tells you exactly when the newest lesson makes the segment invalid.","Only move the left boundary until the overrepresented category is allowed again."],"common_mistakes":["Recomputing category counts for every possible segment.","Moving the left boundary too far after one category exceeds the limit.","Forgetting to decrement counts for lessons that left the active segment."],"follow_up_questions":["How would this change if each category had a different maximum?","How would you process lessons as a stream?","What extra state would late-arriving lesson events require?"],"suboptimal_solutions":[{"name":"Enumerate every segment","complexity":"O(n^2)","description":"Checks many overlapping segments and repeats frequency work."}],"created_at":"2026-01-01T00:00:00Z","updated_at":"2026-01-01T00:00:00Z"}'::jsonb, '{"relative_path":"0012-training-mix-segment/solution.py","language":"python","contents":"# ------------------------------------------------------------\n# [0012-training-mix-segment] Training Mix Segment  |  medium  |  sliding-window\n# ------------------------------------------------------------\n# A training platform records lesson categories in the order a learner completes them. A segment is balanced if no category appears more than max_per_category times inside that contiguous segment. Return the length of the longest balanced segment.\n#\n# Example: lessons=[\"sql\", \"api\", \"sql\", \"sql\", \"testing\"], max_per_category=2 -> 4\n#\n# Full description: call get_problem_description(attempt_id)\n# ------------------------------------------------------------\n\ndef longest_balanced_training_segment(lessons: list[str], max_per_category: int) -> int:\n    \"\"\"Example call and expected return.\n\n    >>> longest_balanced_training_segment([\"sql\", \"api\", \"sql\", \"sql\", \"testing\"], 2)\n    4\n    \"\"\"\n    pass\n","sha256":"84cdb60261303aee01f404aed62ae61766cfb7dde352fee7a6eb530e39cf6d76"}'::jsonb) on conflict (kind, problem_id, revision) do update set available=true;
update public.iwb_content set available=false where kind='coding' and problem_id='0013-signal-triage-board' and revision<>'081b8e435365c74497565bc7eb5c23741175cd8965603810eeb541a5693daabe';
insert into public.iwb_content(kind, problem_id, revision, payload, scaffold) values ('coding', '0013-signal-triage-board', '081b8e435365c74497565bc7eb5c23741175cd8965603810eeb541a5693daabe', '{"id":"0013-signal-triage-board","title":"Signal Triage Board","difficulty":"medium","tags":["heap","array"],"pattern_tags":["top-k","streaming"],"description_md":"A monitoring system receives signals as [severity, timestamp, signal_id]. Higher severity ranks first. Ties prefer the earlier timestamp, then the smaller signal_id. Return the signal_ids for the top k signals in final ranked order.","examples":[{"input":"signals=[[5,10,8],[7,12,3],[7,9,4]], k=2","output":"[4, 3]","explanation":"The two severity 7 signals rank first, and timestamp 9 comes before timestamp 12."}],"constraints":["0 <= len(signals) <= 100000","0 <= k <= 100000","Each signal_id is unique.","severity, timestamp, and signal_id are integers."],"starter_code":{"python":"def top_triage_signals(signals: list[list[int]], k: int) -> list[int]:\n    \"\"\"Example call and expected return.\n\n    >>> top_triage_signals([[5, 10, 8], [7, 12, 3], [7, 9, 4]], 2)\n    [4, 3]\n    \"\"\"\n    pass\n"},"test_cases":{"python":[{"input":[[[5,10,8],[7,12,3],[7,9,4]],2],"expected":[4,3]},{"input":[[],3],"expected":[]},{"input":[[[1,1,1],[2,2,2]],5],"expected":[2,1]},{"input":[[[9,5,10],[9,5,3],[9,4,8]],2],"expected":[8,3]},{"input":[[[3,1,1],[4,1,2],[5,1,3]],0],"expected":[]},{"input":[[[10,100,5],[8,1,1],[10,90,4],[10,90,2]],3],"expected":[2,4,5]},{"input":[[[1,10,1],[2,9,2],[3,8,3],[4,7,4]],2],"expected":[4,3]}]},"canonical_solution_md":"Maintain a bounded set of the current best k signals while scanning the stream. The comparison must encode severity, timestamp, and signal_id so the weakest kept signal can be evicted correctly. After all signals are processed, order the kept candidates by the final ranking and use their ids as the answer. This keeps memory proportional to k rather than the full stream.","fallback_hints":["Only the best k signals need to survive the full scan.","The tie-breakers need to be part of the ranking before anything is discarded.","Keep a bounded structure whose easiest item to remove is the weakest currently kept signal."],"common_mistakes":["Sorting the entire stream after each signal arrives.","Applying timestamp or id tie-breakers only after eviction.","Using a heap direction that evicts the strongest signal instead of the weakest kept signal."],"follow_up_questions":["How would you support score updates for an existing signal_id?","What changes if k is much smaller than the stream size?","How would you return the top k after every prefix of the stream?"],"suboptimal_solutions":[{"name":"Full sort","complexity":"O(n log n)","description":"Works for a single final answer but does not show bounded streaming top-k maintenance."}],"created_at":"2026-01-01T00:00:00Z","updated_at":"2026-01-01T00:00:00Z"}'::jsonb, '{"relative_path":"0013-signal-triage-board/solution.py","language":"python","contents":"# ------------------------------------------------------------\n# [0013-signal-triage-board] Signal Triage Board  |  medium  |  top-k\n# ------------------------------------------------------------\n# A monitoring system receives signals as [severity, timestamp, signal_id]. Higher severity ranks first. Ties prefer the earlier timestamp, then the smaller signal_id. Return the signal_ids for the top k signals in final ranked order.\n#\n# Example: signals=[[5,10,8],[7,12,3],[7,9,4]], k=2 -> [4, 3]\n#\n# Full description: call get_problem_description(attempt_id)\n# ------------------------------------------------------------\n\ndef top_triage_signals(signals: list[list[int]], k: int) -> list[int]:\n    \"\"\"Example call and expected return.\n\n    >>> top_triage_signals([[5, 10, 8], [7, 12, 3], [7, 9, 4]], 2)\n    [4, 3]\n    \"\"\"\n    pass\n","sha256":"ca34ad4b44d00a486db7c40e232e7429dad55cdf0c6e38acfdb306f6841bbdac"}'::jsonb) on conflict (kind, problem_id, revision) do update set available=true;
update public.iwb_content set available=false where kind='coding' and problem_id='0014-inspection-grant-plan' and revision<>'453439485f7872b95cb78d93e3819009912f9088bf6e2e585041219b828642c4';
insert into public.iwb_content(kind, problem_id, revision, payload, scaffold) values ('coding', '0014-inspection-grant-plan', '453439485f7872b95cb78d93e3819009912f9088bf6e2e585041219b828642c4', '{"id":"0014-inspection-grant-plan","title":"Inspection Grant Plan","difficulty":"medium","tags":["array","dynamic-programming"],"pattern_tags":["prefix-dp","planning"],"description_md":"A compliance team has inspections in a fixed order. Each inspection is [grant_value, cooldown]. If the team accepts inspection i, it earns grant_value but must skip the next cooldown inspections. Return the maximum total grant value the team can earn.","examples":[{"input":"inspections=[[6,1],[2,1],[8,1],[4,0]]","output":"14","explanation":"Accepting inspections 0 and 2 earns 14 while respecting cooldowns."}],"constraints":["0 <= len(inspections) <= 100000","Each inspection is [grant_value, cooldown].","0 <= grant_value <= 1000000000","0 <= cooldown <= 100000"],"starter_code":{"python":"def max_inspection_grants(inspections: list[list[int]]) -> int:\n    \"\"\"Example call and expected return.\n\n    >>> max_inspection_grants([[6, 1], [2, 1], [8, 1], [4, 0]])\n    14\n    \"\"\"\n    pass\n"},"test_cases":{"python":[{"input":[[[6,1],[2,1],[8,1],[4,0]]],"expected":14},{"input":[[]],"expected":0},{"input":[[[5,0]]],"expected":5},{"input":[[[5,2],[100,0],[100,0]]],"expected":200},{"input":[[[10,1],[1,0],[10,0]]],"expected":20},{"input":[[[7,3],[6,0],[6,0],[6,0]]],"expected":18},{"input":[[[4,0],[5,1],[6,0],[1,0]]],"expected":11},{"input":[[[8,2],[9,3],[7,0],[7,0]]],"expected":22}]},"canonical_solution_md":"Use dynamic programming over completed suffixes or prefixes. At each inspection, compare skipping it with accepting it and continuing after the blocked cooldown range. The state stores the best value available from a position after all earlier choices have been resolved. This avoids greedy mistakes because a smaller current grant may allow a better later combination.","fallback_hints":["A large grant can block several later inspections, so local value alone is not enough.","Think about the best total available starting from each position in the order.","At each inspection, compare skipping it with taking it plus the best compatible future total."],"common_mistakes":["Greedily taking the largest visible grant.","Forgetting that cooldown can skip more than one following inspection.","Failing to handle empty or single-inspection inputs."],"follow_up_questions":["How would you recover which inspections were accepted?","What changes if cooldowns are measured by calendar date instead of index count?","How would negative grant values affect the recurrence?"],"suboptimal_solutions":[{"name":"Plain recursion","complexity":"Exponential","description":"Branches on each inspection without remembering repeated subproblems."}],"created_at":"2026-01-01T00:00:00Z","updated_at":"2026-01-01T00:00:00Z"}'::jsonb, '{"relative_path":"0014-inspection-grant-plan/solution.py","language":"python","contents":"# ------------------------------------------------------------\n# [0014-inspection-grant-plan] Inspection Grant Plan  |  medium  |  prefix-dp\n# ------------------------------------------------------------\n# A compliance team has inspections in a fixed order. Each inspection is [grant_value, cooldown]. If the team accepts inspection i, it earns grant_value but must skip the next cooldown inspections. Return the maximum total grant value the team can earn.\n#\n# Example: inspections=[[6,1],[2,1],[8,1],[4,0]] -> 14\n#\n# Full description: call get_problem_description(attempt_id)\n# ------------------------------------------------------------\n\ndef max_inspection_grants(inspections: list[list[int]]) -> int:\n    \"\"\"Example call and expected return.\n\n    >>> max_inspection_grants([[6, 1], [2, 1], [8, 1], [4, 0]])\n    14\n    \"\"\"\n    pass\n","sha256":"d75aebe4fae3dd29687b3777b2ffe67b2ad4a02d4a27ec1cbee5e750752e2b7d"}'::jsonb) on conflict (kind, problem_id, revision) do update set available=true;
update public.iwb_content set available=false where kind='coding' and problem_id='0015-delivery-hold-clusters' and revision<>'fd302942eb545cdf00a18da322423a2858f800866e614e1a6b6d89e2db7f262b';
insert into public.iwb_content(kind, problem_id, revision, payload, scaffold) values ('coding', '0015-delivery-hold-clusters', 'fd302942eb545cdf00a18da322423a2858f800866e614e1a6b6d89e2db7f262b', '{"id":"0015-delivery-hold-clusters","title":"Delivery Hold Clusters","difficulty":"medium","tags":["array","sorting","intervals"],"pattern_tags":["interval-merge","gap-threshold"],"description_md":"A logistics system records delivery holds as [start_day, end_day] ranges. Each range includes its start and end days.\n\nTwo holds are in the same cluster if their ranges have overlap. For holds without overlap, the gap is the distance from end_day of one hold to start_day of the subsequent hold. If the gap is at most grace_days, the holds are in the same cluster. If two clusters contain the same hold, they are one cluster.\n\nReturn a range for each cluster. Use the minimum start day and the maximum end day of the holds in the cluster. Put each cluster after clusters with smaller start_day values.","examples":[{"input":"holds=[[1,3],[5,6],[11,12]], grace_days=2","output":"[[1,6],[11,12]]","explanation":"The gap from day 3 to day 5 is 2 days. The first two holds are in one cluster."}],"constraints":["0 <= len(holds) <= 100000","Each hold is [start_day, end_day] with start_day <= end_day.","0 <= grace_days <= 1000000000","Two holds without overlap are [a, b] and [c, d], with b < c. Their gap is c - b."],"starter_code":{"python":"def merge_delivery_holds(holds: list[list[int]], grace_days: int) -> list[list[int]]:\n    \"\"\"Example call and expected return.\n\n    >>> merge_delivery_holds([[1, 3], [5, 6], [11, 12]], 2)\n    [[1, 6], [11, 12]]\n    \"\"\"\n    pass\n"},"test_cases":{"python":[{"input":[[[1,3],[5,6],[11,12]],2],"expected":[[1,6],[11,12]]},{"input":[[],3],"expected":[]},{"input":[[[4,5]],1],"expected":[[4,5]]},{"input":[[[5,6],[1,2]],2],"expected":[[1,2],[5,6]]},{"input":[[[1,4],[4,8]],0],"expected":[[1,8]]},{"input":[[[1,1],[2,2],[4,4]],1],"expected":[[1,2],[4,4]]},{"input":[[[1,3],[6,7],[10,11]],3],"expected":[[1,11]]}]},"canonical_solution_md":"Sort holds by start_day and keep one active cluster. If the next hold starts within grace_days of the active cluster''s end, merge it by extending the active end if needed. Otherwise, close the active cluster and begin a new one. Because merged clusters can chain through several nearby holds, the active end must be updated after every merge.","fallback_hints":["Nearby holds can belong together even when they do not overlap.","After sorting, compare the next hold with the current active cluster.","Remember that threshold-based connections can chain through several holds."],"common_mistakes":["Merging only direct overlaps and ignoring the grace window.","Failing to update the active cluster end after a merge.","Forgetting to append the final active cluster."],"follow_up_questions":["How can you keep clusters correct when the system gets one new hold at a time?","How can you keep the input hold IDs in each cluster?","How can you change the system if each delivery region has a different grace_days value?"],"suboptimal_solutions":[{"name":"Repeated cluster search","complexity":"O(n^2)","description":"Repeatedly scans for connectable holds instead of sorting once and maintaining the active cluster."}],"created_at":"2026-01-01T00:00:00Z","updated_at":"2026-01-01T00:00:00Z"}'::jsonb, '{"relative_path":"0015-delivery-hold-clusters/solution.py","language":"python","contents":"# ------------------------------------------------------------\n# [0015-delivery-hold-clusters] Delivery Hold Clusters  |  medium  |  interval-merge\n# ------------------------------------------------------------\n# A logistics system records delivery holds as [start_day, end_day] ranges. Each range includes its start and end days.\n#\n# Example: holds=[[1,3],[5,6],[11,12]], grace_days=2 -> [[1,6],[11,12]]\n#\n# Full description: call get_problem_description(attempt_id)\n# ------------------------------------------------------------\n\ndef merge_delivery_holds(holds: list[list[int]], grace_days: int) -> list[list[int]]:\n    \"\"\"Example call and expected return.\n\n    >>> merge_delivery_holds([[1, 3], [5, 6], [11, 12]], 2)\n    [[1, 6], [11, 12]]\n    \"\"\"\n    pass\n","sha256":"653ff051fc34c7b44dbbf81982df05c1f6876ef7a17c85090a0098e41ee8b44b"}'::jsonb) on conflict (kind, problem_id, revision) do update set available=true;
update public.iwb_content set available=false where kind='design' and problem_id='design-following-feed' and revision<>'8ecdd7f0a2937d1bee6e425c920a4ca5bd206d2853da4fe263e2a42242ca253e';
insert into public.iwb_content(kind, problem_id, revision, payload, scaffold) values ('design', 'design-following-feed', '8ecdd7f0a2937d1bee6e425c920a4ca5bd206d2853da4fe263e2a42242ca253e', '{"id":"design-following-feed","title":"Following Feed","difficulty":"hard","tags":["fanout","pagination","read-write-tradeoffs"],"brief_md":"Design a chronological feed of posts from accounts a user follows. Explain the read and write paths, visibility changes, and pagination behavior. Keep ranking and advertising outside the initial scope.","requirements":["Publish a post and read a paginated chronological following feed.","Define visibility of deleted posts and changed follow relationships.","Explain ordering when timestamps tie or clocks differ.","Prevent private posts from leaking through cached or precomputed feeds."],"constraints":["Assume 2 million daily active users and 20 feed opens per active user per day.","A typical user follows 200 accounts; a few publishers have millions of followers.","State an explicit freshness target and its failure behavior.","Older pages may be read while new posts arrive."],"scenarios":["A publisher with five million followers posts repeatedly.","A user unfollows an account during pagination.","A delayed worker processes a post after that post was deleted."],"rubric":[{"key":"requirements","title":"Requirements","prompt":"Which requirements are essential, and which are explicitly out of scope?"},{"key":"api","title":"API and contracts","prompt":"Trace one request end to end. What does success mean to its caller?"},{"key":"data","title":"Data and ownership","prompt":"Who owns the authoritative state, and which access patterns shape its representation?"},{"key":"capacity","title":"Capacity assumptions","prompt":"Name your assumptions and units. Which estimate would actually change a design choice?"},{"key":"tradeoffs","title":"Decisions and tradeoffs","prompt":"What alternative did you reject, and what would make it preferable?"},{"key":"failure_modes","title":"Failure modes","prompt":"Trace a partial failure. What can users observe, and how is recovery bounded?"}],"time_budget_minutes":40,"revision":"8ecdd7f0a2937d1bee6e425c920a4ca5bd206d2853da4fe263e2a42242ca253e","pack_id":"starter-system-design","hints":["Start with one user''s read path. Which correctness decisions belong to ordering, membership, and visibility?","Compare when work happens for reads and writes, including an unusually large publisher.","Trace a delayed update after deletion. What remains authoritative at read time, and which shortcuts are safe?"]}'::jsonb, 'null'::jsonb) on conflict (kind, problem_id, revision) do update set available=true;
update public.iwb_content set available=false where kind='design' and problem_id='design-link-aliases' and revision<>'e5c06d6ace1bc29f87957efd94734f60f23451753593bfa3e53f0ebad7370b65';
insert into public.iwb_content(kind, problem_id, revision, payload, scaffold) values ('design', 'design-link-aliases', 'e5c06d6ace1bc29f87957efd94734f60f23451753593bfa3e53f0ebad7370b65', '{"id":"design-link-aliases","title":"Link Alias Service","difficulty":"medium","tags":["read-heavy","data-model","caching"],"brief_md":"A small publishing platform needs short links for customer campaigns. Design creation and redirection of aliases. Start with a service the team can operate today; justify any added scale or complexity.","requirements":["Create an alias for a destination URL and redirect visitors.","Owners can disable an alias; explain when that change becomes visible.","Define behavior for unknown, expired, and disabled aliases.","Prevent one customer''s aliases from being managed by another customer."],"constraints":["Assume 20 million redirects and 100,000 creations per day, with a 5x peak-to-average factor.","Target p95 redirect latency below 150 ms; explain the boundary of that measurement.","The initial team has four engineers and one region.","Campaign links may be abused; specify a bounded abuse-control approach."],"scenarios":["A popular campaign becomes 30% of redirect traffic.","A malicious destination must be disabled within one minute.","Your primary state store is unavailable for ten minutes."],"rubric":[{"key":"requirements","title":"Requirements","prompt":"Which requirements are essential, and which are explicitly out of scope?"},{"key":"api","title":"API and contracts","prompt":"Trace one request end to end. What does success mean to its caller?"},{"key":"data","title":"Data and ownership","prompt":"Who owns the authoritative state, and which access patterns shape its representation?"},{"key":"capacity","title":"Capacity assumptions","prompt":"Name your assumptions and units. Which estimate would actually change a design choice?"},{"key":"tradeoffs","title":"Decisions and tradeoffs","prompt":"What alternative did you reject, and what would make it preferable?"},{"key":"failure_modes","title":"Failure modes","prompt":"Trace a partial failure. What can users observe, and how is recovery bounded?"}],"time_budget_minutes":40,"revision":"e5c06d6ace1bc29f87957efd94734f60f23451753593bfa3e53f0ebad7370b65","pack_id":"starter-system-design","hints":["Separate creation, redirection, and disabling. What must each caller observe?","Compare the access patterns and correctness needs before deciding where caching is acceptable.","Trace a cached redirect after its owner disables the alias. Make the visibility guarantee and failure behavior explicit."]}'::jsonb, 'null'::jsonb) on conflict (kind, problem_id, revision) do update set available=true;
update public.iwb_content set available=false where kind='design' and problem_id='design-notification-delivery' and revision<>'0cb67e9425272341dc2b9be0688a85d0ed008d3311bf207cd93ced75e52cc89b';
insert into public.iwb_content(kind, problem_id, revision, payload, scaffold) values ('design', 'design-notification-delivery', '0cb67e9425272341dc2b9be0688a85d0ed008d3311bf207cd93ced75e52cc89b', '{"id":"design-notification-delivery","title":"Notification Delivery Pipeline","difficulty":"medium","tags":["queues","idempotency","retries"],"brief_md":"A product sends transactional email and mobile notifications. Design an observable delivery workflow from an accepted request to an external provider. Treat delivery guarantees and user preferences as explicit contracts.","requirements":["Accept notification requests with customer-specific preferences.","Track acceptance, provider handoff, failures, and any delivery signals the provider supports.","Make retries bounded and define duplicate behavior.","Allow an operator to inspect a failed request without exposing another customer''s messages."],"constraints":["Assume 5 million requests per day, with a 10x peak.","Transactional requests should normally reach a provider within 60 seconds.","Provider calls have rate limits, transient errors, and ambiguous timeout outcomes.","Some notifications are no longer useful after their expiry time."],"scenarios":["The primary provider is unavailable for an hour.","A worker crashes after provider acceptance but before recording success.","A user disables a channel while a queued notification waits."],"rubric":[{"key":"requirements","title":"Requirements","prompt":"Which requirements are essential, and which are explicitly out of scope?"},{"key":"api","title":"API and contracts","prompt":"Trace one request end to end. What does success mean to its caller?"},{"key":"data","title":"Data and ownership","prompt":"Who owns the authoritative state, and which access patterns shape its representation?"},{"key":"capacity","title":"Capacity assumptions","prompt":"Name your assumptions and units. Which estimate would actually change a design choice?"},{"key":"tradeoffs","title":"Decisions and tradeoffs","prompt":"What alternative did you reject, and what would make it preferable?"},{"key":"failure_modes","title":"Failure modes","prompt":"Trace a partial failure. What can users observe, and how is recovery bounded?"}],"time_budget_minutes":40,"revision":"0cb67e9425272341dc2b9be0688a85d0ed008d3311bf207cd93ced75e52cc89b","pack_id":"starter-system-design","hints":["List the states you can truthfully observe. Does provider acceptance prove user delivery?","Choose where the request identity survives retries, and which transitions need to be durable.","Trace a crash after a successful external side effect. Explain what your system can guarantee without assuming a transaction with the provider."]}'::jsonb, 'null'::jsonb) on conflict (kind, problem_id, revision) do update set available=true;
update public.iwb_content set available=false where kind='design' and problem_id='design-object-vault' and revision<>'29648e7ff82946b9058b21d55a955a2f2cb5c5e52dc57f2b794a28e299f5a3ec';
insert into public.iwb_content(kind, problem_id, revision, payload, scaffold) values ('design', 'design-object-vault', '29648e7ff82946b9058b21d55a955a2f2cb5c5e52dc57f2b794a28e299f5a3ec', '{"id":"design-object-vault","title":"Object Upload and Retrieval","difficulty":"hard","tags":["storage","integrity","lifecycle"],"brief_md":"A team needs customer-owned object upload, download, listing, and deletion. Design the metadata and object lifecycle, including partial uploads and authorization. Do not assume that upload completion alone proves durability.","requirements":["Upload large objects with retries and verify their integrity.","List a customer''s completed objects and authorize every download.","Define overwrite, concurrent upload, and deletion semantics.","Bound storage consumed by unfinished or abandoned uploads."],"constraints":["Assume 10 million objects, a 20 MB average size, and a 5 GB maximum object size.","Support unreliable clients without restarting every large upload.","The initial deployment uses one region; specify the durability and availability goals separately.","Deletion and retention requirements must be stated rather than assumed."],"scenarios":["A client completes data transfer but times out before receiving confirmation.","Metadata commits while one object-storage operation fails.","An object is deleted while an existing download link is still valid."],"rubric":[{"key":"requirements","title":"Requirements","prompt":"Which requirements are essential, and which are explicitly out of scope?"},{"key":"api","title":"API and contracts","prompt":"Trace one request end to end. What does success mean to its caller?"},{"key":"data","title":"Data and ownership","prompt":"Who owns the authoritative state, and which access patterns shape its representation?"},{"key":"capacity","title":"Capacity assumptions","prompt":"Name your assumptions and units. Which estimate would actually change a design choice?"},{"key":"tradeoffs","title":"Decisions and tradeoffs","prompt":"What alternative did you reject, and what would make it preferable?"},{"key":"failure_modes","title":"Failure modes","prompt":"Trace a partial failure. What can users observe, and how is recovery bounded?"}],"time_budget_minutes":40,"revision":"29648e7ff82946b9058b21d55a955a2f2cb5c5e52dc57f2b794a28e299f5a3ec","pack_id":"starter-system-design","hints":["Name the authoritative states for an unfinished upload and a downloadable object.","Trace retries at the boundary between metadata and object bytes. What identifies the same operation?","Work through confirmation loss and deletion independently. Explain how integrity, authorization, and cleanup interact without assuming atomic cross-system writes."]}'::jsonb, 'null'::jsonb) on conflict (kind, problem_id, revision) do update set available=true;
update public.iwb_content set available=false where kind='design' and problem_id='design-request-admission' and revision<>'8a26148003e84e519cec222a96196161084c910eccb920cc2c2d13c062596163';
insert into public.iwb_content(kind, problem_id, revision, payload, scaffold) values ('design', 'design-request-admission', '8a26148003e84e519cec222a96196161084c910eccb920cc2c2d13c062596163', '{"id":"design-request-admission","title":"Distributed Request Admission","difficulty":"hard","tags":["concurrency","correctness","rate-limiting"],"brief_md":"An API platform needs per-customer request admission across multiple application instances. Define the admission contract before choosing a counter or algorithm. Explain the accuracy-versus-availability tradeoff.","requirements":["Apply separate customer quotas and return a useful rejection response.","State whether the policy permits bursts and how replenishment works.","Define what happens when two instances admit a request concurrently.","Support quota changes without allowing cross-customer interference."],"constraints":["Assume 50,000 admission checks per second across 100 application instances.","An example customer is entitled to 100 requests per second; you must define a precise policy around that number.","Budget 10 ms p95 additional admission latency.","Requests may be retried, and instance clocks may disagree."],"scenarios":["The shared admission state becomes unreachable in one availability zone.","One tenant generates half of all checks.","An operator reduces a quota while requests are in flight."],"rubric":[{"key":"requirements","title":"Requirements","prompt":"Which requirements are essential, and which are explicitly out of scope?"},{"key":"api","title":"API and contracts","prompt":"Trace one request end to end. What does success mean to its caller?"},{"key":"data","title":"Data and ownership","prompt":"Who owns the authoritative state, and which access patterns shape its representation?"},{"key":"capacity","title":"Capacity assumptions","prompt":"Name your assumptions and units. Which estimate would actually change a design choice?"},{"key":"tradeoffs","title":"Decisions and tradeoffs","prompt":"What alternative did you reject, and what would make it preferable?"},{"key":"failure_modes","title":"Failure modes","prompt":"Trace a partial failure. What can users observe, and how is recovery bounded?"}],"time_budget_minutes":40,"revision":"8a26148003e84e519cec222a96196161084c910eccb920cc2c2d13c062596163","pack_id":"starter-system-design","hints":["What exact event consumes quota, and what invariant must hold across concurrent callers?","Work through a tiny burst and a retry before comparing state-placement choices.","Explain a partition: what is the maximum admitted traffic under your failure policy, and which requirement pays for that choice?"]}'::jsonb, 'null'::jsonb) on conflict (kind, problem_id, revision) do update set available=true;
